    "questionAr": "يؤثر ازدواج عزمه $M = 320\\text{ نيوتن.سم}$ على جسم. أُثرت قوتان متوازيتان مقدار كل منهما $F$ عند نقطتين $A$ و $B$ البعد العمودي بينهما $d = 16\\text{ سم}$ لإحداث التوازن. أوجد مقدار القوة $F$.",
