    "questionAr": "تؤثر ست قوى في محيط سداسي منتظم $ABCDEF$ طول ضلعه $L = 26\\text{ سم}$ في ترتيب دوري واحد على الترتيب في الاتجاهات $\\vec{AB}, \\vec{BC}, \\vec{CD}, \\vec{DE}, \\vec{EF}, \\vec{FA}$. وكانت القوى متناسبة مع أطوال الأضلاع بمقياس رسم $m = 2\\text{ نيوتن/سم}$. احسب معيار عزم الازدواج المحصل.",
    "optionsEn": [
      "$M = 4156\\sqrt{3}\\text{ N}\\cdot\\text{cm}$",
      "$M = 4056\\sqrt{3}\\text{ N}\\cdot\\text{cm}$",
      "$M = 3956\\sqrt{3}\\text{ N}\\cdot\\text{cm}$",
      "$M = 4256\\sqrt{3}\\text{ N}\\cdot\\text{cm}$"
    ],
    "optionsAr": [
      "$M = 4156\\sqrt{3}\\text{ نيوتن.سم}$",
      "$M = 4056\\sqrt{3}\\text{ نيوتن.سم}$",
      "$M = 3956\\sqrt{3}\\text{ نيوتن.سم}$",
      "$M = 4256\\sqrt{3}\\text{ نيوتن.سم}$"
    ],
    "correctAnswer": "$M = 4056\\sqrt{3}\\text{ N}\\cdot\\text{cm}$",
    "correctIndex": 1,
    "hintEn": "The area of a regular hexagon of side $L$ is $\\text{Area} = \\frac{3\\sqrt{3}}{2} L^2$. Then $M = 2 m \\times \\text{Area}$.",
    "hintAr": "مساحة السداسي المنتظم ذي الضلع $L$ هي $\\text{المساحة} = \\frac{3\\sqrt{3}}{2} L^2$. ثم يكون العزم $M = 2 m \\times \\text{المساحة}$.",
    "stepByStepSolutionEn": [
      "1. Calculate hexagon area: $\\text{Area} = \\frac{3\\sqrt{3}}{2} (26)^2 = \\frac{3\\sqrt{3}}{2} (676) = 1014\\sqrt{3}\\text{ cm}^2$.",
      "2. Apply Polygon Theorem: $M = 2 \\times m \\times \\text{Area}$.",
      "3. $M = 2 \\times 2 \\times \\left(\\frac{3\\sqrt{3}}{2} \\times 676\\right) = 6 \\times 676\\sqrt{3} = 4056\\sqrt{3}\\text{ N}\\cdot\\text{cm}$."
    ],
    "stepByStepSolutionAr": [
      "١. مساحة السداسي المنتظم: $\\text{المساحة} = \\frac{3\\sqrt{3}}{2} (26)^2 = \\frac{3\\sqrt{3}}{2} (676) = 1014\\sqrt{3}\\text{ سم}^2$.",
      "٢. تطبيق نظرية المضلع: $M = 2 \\times m \\times \\text{المساحة}$.",
      "٣. $M = 2 \\times 2 \\times \\left(\\frac{3\\sqrt{3}}{2} \\times 676\\right) = 4056\\sqrt{3}\\text{ نيوتن.سم}$."
    ],
    "teacherTipEn": "For any regular polygon, remember that forces in cyclic order proportional to sides always reduce to a couple with $M = 2 m A$.",
    "teacherTipAr": "لأي مضلع منتظم، القوى الممثلة بأضلاعه تمثيلاً تاماً في اتجاه دوري واحد تكافئ ازدواجاً عزمه $M = 2 m A$."
