    "questionAr": "معين $ABCD$ طول ضلعه $L = 12\\text{ سم}$ وقياس زاويته $m(\\angle A) = 60^\\circ$. تؤثر أربع قوى في أضلاعه في اتجاه دوري واحد بمقياس رسم $m = 3\\text{ نيوتن/سم}$. أُثرت قوتان متساويتان في المقدار ومتضادتان في الاتجاه مقدار كل منهما $F$ عند الرأسين $A$ و $C$ عموديتين على القطر $AC$ ليتزن المعين. احسب مقدار $F$.",
