      "3. Diagonal $AC = 2 \\times 12 \\cos 30^\\circ = 12\\sqrt{3}\\text{ cm}$.",
      "4. Equilibrium requires $F \\times AC = M_1 \\implies F \\times (12\\sqrt{3}) = 432\\sqrt{3} \\implies F = 3 \\times 12 = 36\\text{ N}$."
