      "٢. عزم ازدواج الأضلاع: $M_1 = 2 \\times 3 \\times \\left(72\\sqrt{3}\\right) = 432\\sqrt{3}\\text{ نيوتن.سم}$.",
      "٣. طول القطر $AC = 2 \\times 12 \\cos 30^\\circ = 12\\sqrt{3}\\text{ سم}$.",
      "٤. شرط الاتزان $F \\times AC = M_1 \\implies F \\times (12\\sqrt{3}) = 432\\sqrt{3} \\implies F = 36\\text{ نيوتن}$."
