      "٢. البعد العمودي بين خطي عمل القوتين هو $d = L \\sin\\theta = 16 \\sin\\theta$.",
      "٣. اتزان الازدواجين: $M = W \\times (L \\sin\\theta) \\implies 96 = 192 \\sin\\theta$.",
      "٤. $\\sin\\theta = \\frac{96}{192} = 0.5 \\implies \\theta = 30^\\circ$."
