    "questionAr": "تؤثر أربع قوى في أضلاع شبه منحرف قائم الزاوية $ABCD$ في ترتيب دوري واحد، حيث $AB \\perp BC$ و $BC \\parallel AD$، و $AB = 9\\text{ سم}$، $BC = 7\\text{ سم}$، $AD = 15\\text{ سم}$. إذا كانت القوى متناسبة مع أطوال الأضلاع بمقياس رسم $m = 2\\text{ نيوتن/سم}$، فاحسب معيار عزم الازدواج المكافئ.",
