    "difficulty": "hots",
    "questionEn": "Two couples act on a square lamina $ABCD$ of side length $a = 16\\text{ cm}$. The first couple is formed by forces of magnitude $F_1 = 22\\text{ N}$ acting along $\\vec{AB}$ and $\\vec{CD}$ with moment $M_1 = +352\\text{ N}\\cdot\\text{cm}$. The second couple is formed by forces $F_2 = 12\\text{ N}$ acting along $\\vec{DA}$ and $\\vec{BC}$ with moment $M_2 = +192\\text{ N}\\cdot\\text{cm}$. Two parallel forces of magnitude $F$ each, separated by distance $d = 16\\text{ cm}$, are applied to balance the system. Find the required magnitude $F$.",
    "questionAr": "يؤثر ازدواجان على صفيحة مربعة $ABCD$ طول ضلعها $a = 16\\text{ سم}$. الازدواج الأول قوتاه مقدارهما $F_1 = 22\\text{ نيوتن}$ تؤثران في $\\vec{AB}$ و $\\vec{CD}$ وعزمه $M_1 = +352\\text{ نيوتن.سم}$. والازدواج الثاني قوتاه مقدارهما $F_2 = 12\\text{ نيوتن}$ تؤثران في $\\vec{DA}$ و $\\vec{BC}$ وعزمه $M_2 = +192\\text{ نيوتن.سم}$. أُثرت قوتان متوازيتان مقدار كل منهما $F$ والبعد العمودي بينهما $d = 16\\text{ سم}$ لإعادة التوازن. أوجد مقدار القوة $F$.",
